from collections import deque


class Solution:
    def maxDistance(self, grid: list[list[int]]) -> int:
        n = len(grid)
        queue = deque((r, c) for r in range(n) for c in range(n) if grid[r][c])   # all land cells are sources
        if len(queue) in (0, n * n):       # no land or no water
            return -1
        seen = [[bool(v) for v in row] for row in grid]
        dist = -1
        while queue:                       # each cell is enqueued at most once: O(n^2)
            dist += 1                      # one BFS level = one more step away from the nearest land
            for _ in range(len(queue)):
                r, c = queue.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < n and not seen[nr][nc]:
                        seen[nr][nc] = True    # mark on enqueue so no cell is queued twice
                        queue.append((nr, nc))
        return dist                        # the last level is the farthest water cell

